// OPEN: a PR without records (pre-gh-807) or a broken read keeps today's
// behavior — reconciliation must never strand a leg.

// Fetches the PR's head sha + current labels in one github_get_pr call
// (labels ride the REST body, same as the query path's prStatus). Returns
// { headSha, labels } or null when the probe fails — callers fail open.
function prHeadAndLabels(repoInfo, prNumber) {
    try {
        var raw = github_get_pr({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: String(prNumber)
        });
        var pr = (typeof raw === 'string') ? JSON.parse(raw) : (raw || {});
        if (!pr || pr.message || !pr.head || !pr.head.sha) return null;
        return {
            headSha: pr.head.sha,
            labels: (pr.labels || []).map(function(l) { return (l && l.name) || l; })
        };
    } catch (e) {
        console.warn('  ⚠️ verdict probe: PR read failed (fail-open): ' + (e.message || e));
        return null;
    }
}

// The gh-728 machine-author allowlist for verdict-record parsing (gh-828
// review round 2): resolved through the same knob chain as every other
// machine-keyed guard (jobParams.machineAuthor → config.machineAuthor).
// Unconfigured → [] — the machineAuthor doctrine: no configured identity,
// no trusted machine input; the verdict guards then degrade to their
// no-records fail-open behavior.
function verdictMachineLogins(effectiveConfig) {
    return machineAuthorModule.machineAuthorLogins(
        machineAuthorModule.resolveMachineAuthor(RUN_JOB_PARAMS, effectiveConfig));
}

// Reads every machine verdict record on the PR (oldest first). Fails open to
// [] — same github_get_pr_comments payload shape as failMarkerState above.
// machineLogins (gh-828 review round 2, forge hardening): the gh-728
// machine-identity allowlist — the marker format is public (this repo), so
// only markers authored by a configured machine login are trusted; an
// empty list trusts nothing (the machineAuthor doctrine) and degrades the
// guards to their no-records fail-open behavior.
function readVerdictRecords(repoInfo, prNumber, machineLogins) {
    try {
        var raw = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: String(prNumber)
        });
        var obj = (typeof raw === 'string') ? JSON.parse(raw) : (raw || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        return reviewVerdictsModule.parseVerdictRecords(list,
            { authorLogins: Array.isArray(machineLogins) ? machineLogins : [] });
    } catch (e) {
        console.warn('  ⚠️ verdict probe: comment read failed (fail-open): ' + (e.message || e));
        return [];
    }
}

// gh-601 shape: the sync github_get_issue tool does NOT throw on 404 — it
// returns the REST error body, which carries `message` and no labels.
function linkedIssueLabels(repoInfo, issueNumber) {
    if (!issueNumber || typeof github_get_issue !== 'function') return null;
    try {
        var res = github_get_issue({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            issueNumber: issueNumber
        });
        var obj = (typeof res === 'string') ? JSON.parse(res) : res;
        if (!obj || typeof obj !== 'object' || obj.message) return null;
        return (obj.labels || []).map(function(l) {
            return (l && (l.name || l)) || l;
        });
    } catch (e) {
        return null;
    }
}

// AC3 — the arming-side sticky-approval gate for arm_rework: the effective
// verdict for the CURRENT head must not be APPROVE, unless BLOCKING threads
// remain (the record's census — suggestions never arm rework). Mirrors the
// rework side's prHasApproved rule (approved once → never re-review) with
// the blocking-thread exception from the gh-807 capability surface. Fails
// open (arm: true) on missing records/head — pre-gh-807 PRs arm as before.
// machineLogins (gh-828 review round 2): the gh-728 machine-author
// allowlist the verdict records are parsed with — forged markers must not
// arm or withhold arms.
function reworkArmGate(repoInfo, ticket, machineLogins) {
    var out = { arm: true, reason: 'no-verdict-records', headShort: null, effective: null };
    var probe = prHeadAndLabels(repoInfo, ticket.prNumber);
    if (!probe) return out;
    out.headShort = String(probe.headSha).substring(0, 7);
    var decision = reviewVerdictsModule.armReworkDecision(
        readVerdictRecords(repoInfo, ticket.prNumber, machineLogins), probe.headSha);
    decision.headShort = out.headShort;
    return decision;
}

// ── gh-840 fail-closed agent:rework consumption ─────────────────────────────
//
// Live dmtools-agents PR #826 (gh-825, 2026-10-10 ~10:00Z): agent:rework
// armed twice, later CONSUMED — and no rework leg ever ran (only review
// legs), no push, 4/6 threads open, no close marker. The consumeLabels
// paths below stamp an audit marker so every consumption is attributable,
// and the restore_rework_arm sweep re-arms a consumption that left machine
// threads unresolved on an unchanged head (js/common/reworkConsumption.js
// is the pure side — markers + the shouldRestoreArm decision).

// One fetch of the PR's raw comment list (same payload shape as
// readVerdictRecords / failMarkerState). Returns [] on any read failure —
// the sweep then finds no consumption evidence and stays quiet (fail
// closed: a missed sweep retries next tick, a bogus restore arms a
// duplicate rework leg).
function prCommentList(repoInfo, prNumber) {
    try {
        var raw = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: prNumber
        });
        var obj = (typeof raw === 'string') ? JSON.parse(raw) : (raw || []);
        return Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
    } catch (e) {
        console.warn('  ⚠️ gh-840: comment read failed (fail-closed): ' + (e.message || e));
        return [];
    }
}

// gh-840 audit log — called from processRule's two consumeLabels branches
// after an agent:rework removal. Posts ONE machine-parseable marker comment
// recording the consumption path (dispatch | cross-anchor) + head, so the
// tick sweep can later tell a bogus consumption from a successful close.
// Non-agent:rework labels and non-github sources are untouched; every
// failure is a logged warn — the audit must never break the consumption.
function auditReworkConsumption(repoInfo, ticket, label, path) {
    if (label !== reviewVerdictsModule.LABEL_REWORK) return;
    if (!ticket || !ticket.prNumber) {
        console.warn('  ⚠️ gh-840: agent:rework consumed on ' + (ticket && ticket.key) +
            ' with no PR anchor — audit marker skipped');
        return;
    }
    var head = ((ticket.pr && ticket.pr.headSha) || ticket.headSha) || null;
    var body = reworkConsumptionModule.buildConsumeAuditComment(path, head);
    if (!body) return;
    if (DRY) { console.log('  [dry] 🏷️ gh-840 consumption audit (' + path + ') on PR #' + ticket.prNumber); return; }
    try {
        github_create_comment({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            number: ticket.prNumber, body: body
        });
        console.log('  🏷️  gh-840: agent:rework consumption audited (path: ' + path +
