    if (!decision.restore) {
        console.log('  ⏭️  ' + key + ' sweep: no restore (' + decision.reason + ')');
        return false;
    }
    github_add_labels({
        workspace: repoInfo.owner, repository: repoInfo.repo,
        number: prNumber, labels: ['agent:rework']
