        var pr = (typeof raw === 'string') ? JSON.parse(raw) : (raw || {});
        if (!pr || pr.message || !pr.head || !pr.head.sha) return null;
        return {
            headSha: pr.head.sha,
            labels: (pr.labels || []).map(function(l) { return (l && l.name) || l; })
