            fileMap: { '../.dmtools/config.js': 'module.exports = { repository: { owner: "epam", repo: "dmtools-agents" } };' },
            github: {
                items: [{ key: 'pr-826', labels: ['ai_pr_reviewed'], issueNumber: 825, prNumber: 826,
                    draft: false, author: 'ai-teammate',
