        ? s.consumedAtMs : null;
    var restored = (typeof s.restoredAtMs === 'number' && !isNaN(s.restoredAtMs))
        ? s.restoredAtMs : null;
    if (consumed === null && restored === null) {
        return { restore: false, reason: 'no-consumption-evidence' };
    }
