                          headSha: ADVANCED } }],
                pr: { number: 826, head: { sha: ADVANCED }, labels: [{ name: 'ai_pr_reviewed' }], body: 'Fixes #825' },
                prComments: [consumeComment('dispatch', '2026-10-10T10:00:00.000Z')],
