{"newText":"/**
 * The sweep decision (pure — gh-840 AC1–AC3). state:
 *   unresolvedMachineThreads        — unresolved threads authored by the
 *                                     machine (the caller's census; >0 is
 *                                     the "threads to own" proof and the
 *                                     ONLY close-proof inverse — a healthy
 *                                     close resolves the machine threads);
 *   hasReworkLabel                  — agent:rework present on the PR;
 *   reworkInFlight                  — gh-806 latch OR an active leg run on
 *                                     the head;
 *   consumedAtMs / restoredAtMs     — newest marker timestamps (null when
 *                                     no evidence exists);
 *   nowMs, staleMs                  — the clock and the quiet bound.
 * Returns { restore, reason }:
 *   'restore'                  — re-arm agent:rework + restore comment;
 *   'no-unresolved-threads'    — nothing to own (AC2 close proof);
 *   'arm-present'              — the label is there; the armer owns it;
 *   'rework-in-flight'         — a leg owns the threads;
 *   'no-consumption-evidence'  — never consumed (AC3 — human-thread-only
 *                                PRs untouched);
 *   'within-grace'             — quiet window not elapsed (bounded re-arm);
 *   'bad-clock'                — missing/unparsable clock → fail closed.
 *
 * IMPORTANT (gh-840 rework review): there is deliberately NO head-position
 * gate. silentUpdateBranch's silent refresh merges advance the head without
 * a leg and without resolving threads; an advanced head carrying the same
 * open machine threads is refresh evidence, not close evidence. Head
 * position is still consulted by the caller for the gh-806 latch, the
 * in-flight leg gate and the marker bookkeeping — never as a close proof.
 */
function shouldRestoreArm(state) {
    var s = state || {};
    if (s.hasReworkLabel) return { restore: false, reason: 'arm-present' };
    if (s.reworkInFlight) return { restore: false, reason: 'rework-in-flight' };
    if (!(Number(s.unresolvedMachineThreads) > 0)) {
        return { restore: false, reason: 'no-unresolved-threads' };
    }
    var consumed = (typeof s.consumedAtMs === 'number' && !isNaN(s.consumedAtMs))
        ? s.consumedAtMs : null;","oldText":"/**
 * The sweep decision (pure — gh-840 AC1–AC3). state:
 *   unresolvedMachineThreads        — unresolved threads authored by the
 *                                     machine (the caller's census; >0 is
 *                                     the "threads to own" proof);
 *   hasReworkLabel                  — agent:rework present on the PR;
 *   reworkInFlight                  — gh-806 latch OR an active leg run on
 *                                     the head;
 *   consumedAtMs / restoredAtMs     — newest marker timestamps (null when
 *                                     no evidence exists);
 *   headAdvancedPastConsumption     — the live head differs from the newest
 *                                     consume marker's head (a push/refresh
 *                                     happened after the consumption — the
 *                                     leg-close marker: comment + head
 *                                     advanced);
 *   nowMs, staleMs                  — the clock and the quiet bound.
 * Returns { restore, reason }:
 *   'restore'                  — re-arm agent:rework + restore comment;
 *   'no-unresolved-threads'    — nothing to own (AC2 close proof);
 *   'arm-present'              — the label is there; the armer owns it;
 *   'rework-in-flight'         — a leg owns the threads;
 *   'no-consumption-evidence'  — never consumed (AC3 — human-thread-only
 *                                PRs untouched);
 *   'head-advanced'            — a push followed the consumption (AC2);
 *   'within-grace'             — quiet window not elapsed (bounded re-arm);
 *   'bad-clock'                — missing/unparsable clock → fail closed.
 */
function shouldRestoreArm(state) {
    var s = state || {};
    if (s.hasReworkLabel) return { restore: false, reason: 'arm-present' };
    if (s.reworkInFlight) return { restore: false, reason: 'rework-in-flight' };
    if (!(Number(s.unresolvedMachineThreads) > 0)) {
        return { restore: false, reason: 'no-unresolved-threads' };
    }
    if (s.headAdvancedPastConsumption) {
        return { restore: false, reason: 'head-advanced' };
    }
    var consumed = (typeof s.consumedAtMs === 'number' && !isNaN(s.consumedAtMs))
        ? s.consumedAtMs : null;","path":"js/common/reworkConsumption.js"}

{"newText":"// ── gh-840 fail-closed agent:rework consumption ─────────────────────────────
//
// Live dmtools-agents PR #826 (gh-825, 2026-10-10 ~10:00Z): agent:rework
// armed twice, later CONSUMED — and no rework leg ever ran (only review
// legs), no push, 4/6 threads open, no close marker. The consumeLabels
// paths below stamp an audit marker so every consumption is attributable,
// and the restore_rework_arm sweep re-arms a consumption that left machine
// threads unresolved (js/common/reworkConsumption.js is the pure side —
// markers + the shouldRestoreArm decision).
//
// gh-840 rework review (BLOCKING): PR-carrier query items usually carry
// pr: null — githubSource queryPrs populates item.pr only under
// needsStatus (checks/mergeState/prChecks/verdict query keys), and neither
// rework-on-label nor the rework-arm-restore query carries any. Both paths
// below therefore probe the head fresh through prHeadAndLabels (the same
// fresh-probe pattern reworkArmGate already uses) whenever the query item
// has none.

// One fetch of the PR's raw comment list (same payload shape as
// readVerdictRecords / failMarkerState). Returns [] on any read failure —
// the sweep then finds no consumption evidence and stays quiet (fail
// closed: a missed sweep retries next tick, a bogus restore arms a
// duplicate rework leg).
function prCommentList(repoInfo, prNumber) {
    try {
        var raw = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: String(prNumber)
        });
        var obj = (typeof raw === 'string') ? JSON.parse(raw) : (raw || []);
        return Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
    } catch (e) {
        console.warn('  ⚠️ gh-840: comment read failed (fail-closed): ' + (e.message || e));
        return [];
